import pandas as pd,numpy as np
from pymatgen.io.vasp import Poscar
x=pd.read_csv('nlo_pool.csv').set_index('candidate_id')
for k in ['c007','c040','c041','c042','c043','c044','c045','c048','c062','c066','c083','c089']:
 s=Poscar.from_str(x.loc[k,'poscar']).structure
 print('\n',k)
 if 'B' in s.symbol_set:
  tensors=[]
  for site in s:
   if site.specie.symbol!='B':continue
   ns=sorted([n for n in s.get_neighbors(site,2.3) if n.specie.symbol in ['S','P','As']],key=lambda n:n.nn_distance)
   vec=np.array([n.coords-site.coords for n in ns]); u=vec/np.linalg.norm(vec,axis=1)[:,None]
   if len(u)==3:
    _,ss,v=np.linalg.svd(vec)
    norm=v[-1]; tensors.append(np.outer(norm,norm))
    print('B plane normal',np.round(norm,3),'flatness',ss[-1]/ss[0])
   elif len(u)==2:
    print('linear angle',np.rad2deg(np.arccos(np.clip(u[0]@u[1],-1,1))), 'axis',np.round(u[0],3));tensors.append(np.outer(u[0],u[0]))
  t=np.mean(tensors,axis=0);print('orientation eigs',np.linalg.eigvalsh(t), 'normalized anisotropy density', np.ptp(np.linalg.eigvalsh(t))*len(tensors)/s.volume)
 else:
  for i,site in enumerate(s):
   if site.specie.symbol not in ['As','Cu','Se']:continue
   for n in s.get_neighbors(site,2.8):
    if n.specie.symbol in ['As','Te','Se','S']:
     print(i,site.specie,'to',n.index,n.specie,'img',n.image,'vec',np.round(n.coords-site.coords,3), 'd', round(n.nn_distance,3))
